parameters.jsonBody:
={
  "sender": {
    "name": "ระบบบริหารจัดการวันลา",
    "email": "leavemanagementbru@gmail.com"
  },
  "to": [
    {
      "email": "{{ $json.body.user.email }}"
    }
  ],
  "subject": "[แจ้งผลการลา] {{ $json.body.status === 'confirmed' ? 'อนุมัติเรียบร้อยแล้ว' : ($json.body.status === 'approved' ? 'ผ่านการรับรองจากหัวหน้างาน' : 'ไม่อนุมัติ') }} - {{ $json.body.leaveType.name }}",
  "htmlContent": "<div style=\"font-family: sans-serif; max-width: 600px; margin: 0 auto;\"><div style=\"background: linear-gradient(135deg, #667eea, #764ba2); padding: 20px; border-radius: 10px 10px 0 0;\"><h2 style=\"color: white; margin: 0;\">🔔 แจ้งเตือนสถานะคำขอลา</h2></div><div style=\"background: white; padding: 20px; border: 1px solid #e2e8f0;\"><p>เรียนคุณ <strong>{{ $json.body.user.firstName }} {{ $json.body.user.lastName }}</strong></p><p>คำขอลาของคุณได้รับการอัปเดตสถานะเป็น: <strong style=\"color: {{ $json.body.status === 'confirmed' ? '#10b981' : ($json.body.status === 'approved' ? '#3b82f6' : '#ef4444') }};\">{{ $json.body.status === 'confirmed' ? 'อนุมัติและบันทึกข้อมูลลงระบบเรียบร้อยแล้ว' : ($json.body.status === 'approved' ? 'ผ่านการรับรองจากหัวหน้างานแล้ว (รอแอดมินยืนยัน)' : 'ไม่อนุมัติ') }}</strong></p><hr style=\"border: none; border-top: 1px solid #e2e8f0; margin: 15px 0;\"><p><strong>ประเภทการลา:</strong> {{ $json.body.leaveType.name }}</p><p><strong>จำนวนวัน:</strong> {{ $json.body.leaveRequest.totalDays }} วัน</p><p><strong>หมายเหตุ/เหตุผลประกอบ:</strong> {{ $json.body.note || '-' }}</p><div style=\"margin-top: 20px;\"><a href=\"{{ $json.body.frontendUrl }}/history\" style=\"background: linear-gradient(135deg, #667eea, #764ba2); color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px;\">ตรวจสอบประวัติการลา</a></div></div></div>"
}
